arguments.command:
SYMDIR="/tmp/sv-0154737d1dc94438ae5ff544962446d9/symbols"
DBG="$SYMDIR/libmonosgen-2.0.so.dbg"

# Try to find nearest symbols with nm sorted by address
aarch64-linux-gnu-nm --defined-only "$DBG" 2>/dev/null | sort | awk '
{
  addr = strtonum("0x"$1)
  if (addr <= 0x2f4b20) { prev1 = $0 }
  if (addr <= 0x2f4c84) { prev2 = $0 }
}
END { print "Nearest to 0x2f4b20: " prev1; print "Nearest to 0x2f4c84: " prev2 }
'

